import{_ as d,a0 as r,w as n,s as p,I as o,x as s,a1 as a,A as l,ao as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"Bash 5.0 发布及其新功能 | LCTT x X-CMD","titleTemplate":false,"description":"Bash 5.0 发布及其新功能 | LCTT (201901) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Bash 5.0 发布及其新功能 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Bash 5.0 发布及其新功能 | LCTT (201901) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201901/20190109 Bash 5.0 Released with New Features","title":"Bash 5.0 发布及其新功能","tag":"201901","desc":""},"relativePath":"201901/20190109 Bash 5.0 Released with New Features.md","filePath":"[post].md"}'),h={name:"201901/20190109 Bash 5.0 Released with New Features.md"};function u(b,e,f,m,g,B){const t=r("Link");return n(),p("div",null,[e[23]||(e[23]=o("h1",{id:"bash-5-0-发布及其新功能",tabindex:"-1"},[s("Bash 5.0 发布及其新功能 "),o("a",{class:"header-anchor",href:"#bash-5-0-发布及其新功能","aria-label":"Permalink to “Bash 5.0 发布及其新功能”"},"​")],-1)),o("p",null,[a(t,{href:"https://lists.gnu.org/archive/html/bug-bash/2019-01/msg00063.html"},{default:l(()=>[...e[0]||(e[0]=[s("邮件列表",-1)])]),_:1}),e[1]||(e[1]=s("证实最近发布了 Bash-5.0。而且，令人兴奋的是它还有新的功能和变量。",-1))]),o("p",null,[e[3]||(e[3]=s("如果你一直在使用 Bash 4.4.XX，那么你一定会喜欢 ",-1)),a(t,{href:"https://www.gnu.org/software/bash/"},{default:l(()=>[...e[2]||(e[2]=[s("Bash",-1)])]),_:1}),e[4]||(e[4]=s(" 的第五个主要版本。",-1))]),e[24]||(e[24]=i('<p>第五个版本侧重于新的 shell 变量和许多重大漏洞修复。它还引入了一些新功能，以及一些与 bash-4.4 不兼容的更改。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2019/01/bash-logo.jpg?resize=800%2C450&amp;ssl=1" alt="Bash logo"></p><h3 id="新功能怎么样" tabindex="-1">新功能怎么样？ <a class="header-anchor" href="#新功能怎么样" aria-label="Permalink to “新功能怎么样？”">​</a></h3><p>在邮件列表解释了此版本中修复的 bug：</p><blockquote><p>此版本修复了 bash-4.4 中的几个主要错误，并引入了几个新功能。最重要的 bug 修复是对 nameref 变量的解析以及通过模糊测试发现的许多潜在的内存越界错误。在为了符合 Posix 标准解释而不进行单词拆分的上下文中，对 <code>$@</code> 和 <code>$*</code> 的展开做了许多改变，另外还有解决极端情况中 Posix 一致性的修改。</p></blockquote><p>它还引入了一些新功能。根据其发布说明，最值得注意的新功能是几个新的 shell 变量：</p><blockquote><p><code>BASH_ARGV0</code>、<code>EPOCHSECONDS</code> 和 <code>EPOCHREALTIME</code>。内置命令 <code>history</code> 可以删除指定范围的条目，并能将负数理解为从历史末端开始的偏移量。有一个选项允许局部变量继承前一个范围内具有相同名称的变量的值。有一个新的 shell 选项，在启用它时，会导致 shell 只尝试一次扩展关联数组下标（这在算术表达式中使用时会出现问题）。<code>globasciiranges</code> 这个 shell 选项现在默认启用。可以在配置时默认关闭它。</p></blockquote><h3 id="bash-4-4-和-bash-5-0-之间有哪些变化" tabindex="-1">Bash-4.4 和 Bash-5.0 之间有哪些变化？ <a class="header-anchor" href="#bash-4-4-和-bash-5-0-之间有哪些变化" aria-label="Permalink to “Bash-4.4 和 Bash-5.0 之间有哪些变化？”">​</a></h3><p>其更新日志提到了不兼容的更改和所支持的 readline 版本历史记录。它是这么说的：</p><blockquote><p>bash-4.4 和 bash-5.0 之间存在一些不兼容的变化。尽管我已经尽量最小化兼容性问题，但是对 <code>nameref</code> 变量解析的更改意味着对变量名引用的某些使用会有不同的行为。默认情况下，如果启用了扩展调试模式，shell 仅在启动时设置 <code>BASH_ARGC</code> 和 <code>BASH_ARGV</code>。它被无条件地设置是一个疏忽，并且在脚本传递大量参数时会导致性能问题。</p><p>如果需要，可以将 Bash 链接到已安装的 Readline 库，而不是 <code>lib/readline</code> 中的私有版本。只有 readline-8.0 及更高版本能够提供 bash-5.0 所需的所有符号。早期版本的 Readline 库无法正常工作。</p></blockquote><p>我相信一些添加的功能/变量非常有用。我最喜欢的一些是：</p><ul><li>有一个新的（默认情况下禁用，文档中没有说明）shell 选项，用于在运行时启用/禁用向 syslog 发送历史记录。</li><li>正如文档一直所说的那样，除非 shell 处于调试模式，否则它不会在启动时自动设置 <code>BASH_ARGC</code> 和 <code>BASH_ARGV</code>，但如果脚本在上层引用它们且没有启用调试模式，那么 shell 将动态创建它们。</li><li>现在可以使用 <code>-d start-end</code> 删除指定范围的 <code>history</code> 条目。</li><li>如果启用了作业控制的非交互式 shell 检测到前台作业因 SIGINT 而死亡，则其行为就像接收到 SIGINT 一样。</li><li><code>BASH_ARGV0</code>：一个新变量，扩展为 <code>$0</code>，并在赋值时设置为 <code>$0</code>。</li></ul>',12)),o("p",null,[e[6]||(e[6]=s("要查看完整的更改和功能列表，请参阅",-1)),a(t,{href:"https://lists.gnu.org/archive/html/bug-bash/2019-01/msg00063.html"},{default:l(()=>[...e[5]||(e[5]=[s("邮件列表文章",-1)])]),_:1}),e[7]||(e[7]=s("。",-1))]),e[25]||(e[25]=i('<h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>你可以使用下面的命令检查你当前的 Bash 版本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>bash --version</span></span></code></pre></div><p>你很可能安装了 Bash 4.4。如果你想获得新版本，我建议等待你的发行版提供它。</p><p>你怎么看待 Bash-5.0 发布？你在使用其他 bash 的替代品么？如果有的话，这个更新会改变你的想法么？</p><p>请在下面的评论中告诉我们你的想法。</p><hr>',7)),o("p",null,[e[9]||(e[9]=s("via: ",-1)),a(t,{href:"https://itsfoss.com/bash-5-release"},{default:l(()=>[...e[8]||(e[8]=[s("https://itsfoss.com/bash-5-release",-1)])]),_:1})]),o("p",null,[e[14]||(e[14]=s("作者：",-1)),a(t,{href:"https://itsfoss.com/author/ankush/"},{default:l(()=>[...e[10]||(e[10]=[s("Ankush Das",-1)])]),_:1}),e[15]||(e[15]=s(" 选题：",-1)),a(t,{href:"https://github.com/lujun9972"},{default:l(()=>[...e[11]||(e[11]=[s("lujun9972",-1)])]),_:1}),e[16]||(e[16]=s(" 译者：",-1)),a(t,{href:"https://github.com/geekpi"},{default:l(()=>[...e[12]||(e[12]=[s("geekpi",-1)])]),_:1}),e[17]||(e[17]=s(" 校对：",-1)),a(t,{href:"https://github.com/wxy"},{default:l(()=>[...e[13]||(e[13]=[s("wxy",-1)])]),_:1})]),o("p",null,[e[20]||(e[20]=s("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...e[18]||(e[18]=[s("LCTT",-1)])]),_:1}),e[21]||(e[21]=s(" 原创编译，",-1)),a(t,{href:"https://linux.cn/"},{default:l(()=>[...e[19]||(e[19]=[s("Linux中国",-1)])]),_:1}),e[22]||(e[22]=s(" 荣誉推出",-1))])])}const A=d(h,[["render",u]]);export{C as __pageData,A as default};
